# Generated by scripts/build-deploy.sh — do not edit directly.
# setup-cursor-ide-mcp.ps1 — Installs/updates MCP servers for Cursor IDE on Windows
# Safe to re-run — merges managed servers into ~/.cursor/mcp.json.
#
# Managed fields: mcpServers.chrome-devtools, mcpServers.vercel, mcpServers.webflow
# Preserved: all other mcpServers entries, all other top-level keys
#
# All three servers at user level. Chrome DevTools enabled globally;
# Vercel and Webflow are present but disabled via `agent mcp disable`.
# Use `aitools --addmcp` to enable per project.
#
# Cursor uses its own MCP config at ~/.cursor/mcp.json (separate from Claude Code's ~/.claude.json).
# Remote servers use the "url" key directly. Local stdio servers use "command" + "args".

param(
    [switch]$DryRun,
    [switch]$Force
)

# Env passthrough from parent (aitools CLI)
if ($env:AITOOLS_DRY_RUN -eq "1") { $DryRun = [switch]::Present }

# --- Shared library ---
# aitools-lib.ps1 -- shared helpers for all aitools PowerShell scripts
# Dot-sourced, not executed directly.
#
# Provides: ReadConfigKey, Initialize-Logging, Log/LogOk/LogError/LogWarn,
# Write-Summary, Show-Summary.
#
# Usage:
#   . (Join-Path (Split-Path -Parent $MyInvocation.MyCommand.Path) "aitools-lib.ps1")
#   Initialize-Logging "script-name"
#
# Entry points (aitools.ps1, aitools-install.ps1) override log functions after
# sourcing for specialized logging (file-only, JSONL, etc.).
#
# Platform detection uses PS 7+ built-in $IsMacOS/$IsWindows -- no custom variables.

# ---------------------------------------------------------------------------
# Config reader (PS 5.1 compatible)
# ---------------------------------------------------------------------------
function ReadConfigKey {
    param([string]$File, [string]$Key)
    if (-not (Test-Path $File)) { return $null }
    try {
        $json = Get-Content $File -Raw -ErrorAction Stop | ConvertFrom-Json
        $val = $json.$Key
        if ($val) { return $val }
    } catch {
        # File exists but is invalid JSON -- warn so callers know the null
        # return means "corrupt", not "missing key"
        Write-Host "      WARN: could not parse $File" -ForegroundColor Yellow
    }
    return $null
}

# ---------------------------------------------------------------------------
# Logging init
# ---------------------------------------------------------------------------
# Sets $script:scriptName, $script:logDir, $script:logFile, $script:errors.
# Creates log directory.
# Usage: Initialize-Logging "setup-foo"
function Initialize-Logging {
    param([Parameter(Mandatory)][string]$Name)
    $script:scriptName = $Name
    if ($IsWindows -or (-not (Test-Path variable:IsMacOS))) {
        # Windows (PS 7+) or PS 5.1 (always Windows)
        $script:logDir = Join-Path $env:LOCALAPPDATA "aitools"
    } else {
        # macOS/Linux
        $script:logDir = Join-Path $HOME "Library/Logs/aitools"
    }
    $script:logFile = Join-Path $script:logDir "deploy.log"
    if (-not (Test-Path $script:logDir)) {
        New-Item -ItemType Directory -Path $script:logDir -Force | Out-Null
    }
    $script:errors = 0
}

# ---------------------------------------------------------------------------
# Standard logging (console + log file)
# ---------------------------------------------------------------------------
function Log($msg) {
    $ts = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")
    $line = "[$ts] [$scriptName] $msg"
    Write-Host $line
    Add-Content -Path $logFile -Value $line
}
function LogOk($msg)    { Log "OK: $msg" }
function LogError($msg) { Log "ERROR: $msg"; $script:errors++ }
function LogWarn($msg)  { Log "WARN: $msg" }

# ---------------------------------------------------------------------------
# Summary writer (3-arg: category, tool, detail)
# ---------------------------------------------------------------------------
function Write-Summary($cat, $tool, $detail) {
    if ($env:AITOOLS_SUMMARY_FILE) {
        Add-Content -Path $env:AITOOLS_SUMMARY_FILE -Value "${cat}|${tool}|${detail}"
    }
}

# ---------------------------------------------------------------------------
# Summary panel renderer
# ---------------------------------------------------------------------------
# Reads AITOOLS_SUMMARY_FILE, displays colored panel, cleans up.
# Silent no-op if file unset, missing, or empty.
function Show-Summary {
    $sfile = $env:AITOOLS_SUMMARY_FILE
    if (-not $sfile -or -not (Test-Path $sfile)) { return }
    $lines = Get-Content $sfile -ErrorAction SilentlyContinue
    if (-not $lines) { Remove-Item $sfile -ErrorAction SilentlyContinue; return }
    Write-Host ""
    Write-Host "------------------------------------------------------------"
    foreach ($line in $lines) {
        $parts = $line -split '\|', 3
        if ($parts[0] -eq 'OK') { Write-Host ("  [ok]  {0,-16} {1}" -f $parts[1], $parts[2]) -ForegroundColor Green }
    }
    foreach ($line in $lines) {
        $parts = $line -split '\|', 3
        if ($parts[0] -eq 'WARN') { Write-Host ("  [!]   {0,-16} {1}" -f $parts[1], $parts[2]) -ForegroundColor Yellow }
    }
    foreach ($line in $lines) {
        $parts = $line -split '\|', 3
        if ($parts[0] -eq 'ERROR') { Write-Host ("  [ERR] {0,-16} {1}" -f $parts[1], $parts[2]) -ForegroundColor Red }
    }
    $firstAction = $true
    foreach ($line in $lines) {
        $parts = $line -split '\|', 3
        if ($parts[0] -eq 'ACTION') {
            if ($firstAction) {
                Write-Host ""
                Write-Host "  ACTION REQUIRED -- run before tools are ready:" -ForegroundColor Magenta
                $firstAction = $false
            }
            Write-Host "  >>  $($parts[2])" -ForegroundColor Magenta
        }
    }
    Write-Host "------------------------------------------------------------"
    Remove-Item $sfile -ErrorAction SilentlyContinue
}
Initialize-Logging "setup-cursor-ide-mcp"

# Backup a file before overwriting. Keeps at most $MaxBackups copies.
function Backup-File {
    param([string]$FilePath, [int]$MaxBackups = 20)
    if (-not (Test-Path $FilePath)) { return }
    $ts = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHHmmssZ")
    $backupPath = "${FilePath}.bak.${ts}"
    Copy-Item -Path $FilePath -Destination $backupPath
    # Prune oldest beyond limit
    $backups = Get-ChildItem -Path "${FilePath}.bak.*" | Sort-Object LastWriteTime -Descending
    if ($backups.Count -gt $MaxBackups) {
        $backups | Select-Object -Skip $MaxBackups | Remove-Item -Force
    }
    Log "Backed up $FilePath"
}

# --- PS 5.1 compatibility helper ---
# ConvertFrom-Json -AsHashtable is PS 6+ only. This converts PSCustomObject trees
# to nested hashtables so .ContainsKey() and bracket indexing work on PS 5.1.
function ConvertPSObjectToHashtable($obj) {
    if ($null -eq $obj) { return @{} }
    $ht = @{}
    foreach ($prop in $obj.PSObject.Properties) {
        if ($prop.Value -is [System.Management.Automation.PSCustomObject]) {
            $ht[$prop.Name] = ConvertPSObjectToHashtable $prop.Value
        } else {
            $ht[$prop.Name] = $prop.Value
        }
    }
    return $ht
}

# --- OS guard ---
if ($PSVersionTable.PSVersion.Major -ge 6 -and -not $IsWindows) {
    LogError "This script is for Windows. On macOS/Linux, use the .sh version."
    exit 1
}

if ($DryRun) { Log "[DRY RUN] Preview mode -- no files will be written" }

Log "Setting up MCP servers for Cursor IDE (user scope)..."

# Check that Node.js is available (required for Chrome DevTools MCP)
if (-not (Get-Command node -ErrorAction SilentlyContinue)) {
    LogError "Node.js not found. Install via 'aitools install' or manually: https://nodejs.org"
    exit 1
} else {
    $nodeVersion = (node --version)
    LogOk "Node.js $nodeVersion found"
}

# Ensure ~/.cursor directory exists
$cursorDir = Join-Path $env:USERPROFILE ".cursor"
if (-not (Test-Path $cursorDir)) {
    New-Item -ItemType Directory -Path $cursorDir -Force | Out-Null
    Log "Created $cursorDir"
}

$mcpJson = Join-Path $cursorDir "mcp.json"

# Read existing config or start fresh (merge, not overwrite)
if (-not $DryRun) {
    Backup-File -FilePath $mcpJson
}
$config = @{}
$corrupt = $false
if (Test-Path $mcpJson) {
    Log "Merging managed servers into $mcpJson"
    try {
        $raw = Get-Content $mcpJson -Raw
        $config = ConvertPSObjectToHashtable ($raw | ConvertFrom-Json)
    } catch {
        $corrupt = $true
        LogWarn "$mcpJson could not be parsed ($_)"
    }
} else {
    Log "Creating $mcpJson"
}
$beforeKeys = @($config.Keys)

# Ensure mcpServers exists
if (-not $config.ContainsKey("mcpServers")) { $config["mcpServers"] = @{} }

# Set managed servers (Windows uses cmd /c wrapper for npx)
$config["mcpServers"]["chrome-devtools"] = @{
    command = "cmd"
    args    = @("/c", "npx", "-y", "chrome-devtools-mcp@latest", "--isolated")
}
$config["mcpServers"]["vercel"] = @{
    url = "https://mcp.vercel.com"
}
$config["mcpServers"]["webflow"] = @{
    url = "https://mcp.webflow.com/mcp"
}

# Clobber detection
$managedKeys = @("mcpServers")
$lostKeys = @($beforeKeys | Where-Object { $_ -notin $config.Keys })

if ($DryRun) {
    Log "[DRY RUN] $mcpJson`: merge MCP servers"
    Log "  Managed fields: mcpServers.chrome-devtools, mcpServers.vercel, mcpServers.webflow"
    if ($lostKeys.Count -gt 0) {
        LogWarn "[DRY RUN] CLOBBER: would lose non-managed fields: $($lostKeys -join ', ')"
    }
    if ($corrupt) {
        LogWarn "[DRY RUN] File is corrupt -- -Force required to overwrite"
    }
} elseif ($corrupt -and -not $Force) {
    LogError "$mcpJson is corrupt. Use -Force to overwrite, or fix manually."
} elseif ($lostKeys.Count -gt 0 -and -not $Force) {
    LogError "$mcpJson merge would lose fields: $($lostKeys -join ', '). Use -Force to proceed."
} else {
    if ($corrupt) { LogWarn "Proceeding with -Force on corrupt file" }
    if ($lostKeys.Count -gt 0) { LogWarn "Proceeding with -Force, losing fields: $($lostKeys -join ', ')" }

    $json = $config | ConvertTo-Json -Depth 10
    $resolvedPath = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($mcpJson)
    [System.IO.File]::WriteAllText($resolvedPath, $json, [System.Text.UTF8Encoding]::new($false))

    # Post-write validation
    try {
        $vContent = [System.IO.File]::ReadAllText($resolvedPath)
        $vParsed = $vContent | ConvertFrom-Json
        if (-not ($vParsed.PSObject.Properties.Name -contains "mcpServers")) {
            LogError "Validation failed: $mcpJson missing required field 'mcpServers'"
        }
    } catch {
        LogError "Validation failed: $mcpJson is not valid JSON -- $_"
    }

    LogOk "Cursor MCP config written to $mcpJson"
    Log "Servers configured: chrome-devtools (stdio), vercel (http), webflow (http)"
    Write-Summary "OK" "cursor ide mcp" "merged"
}

# --- Disable vercel/webflow via Cursor CLI if available ---
if ($DryRun) {
    Log "[DRY RUN] Would disable vercel/webflow via Cursor CLI (if available)"
} elseif (Get-Command agent -ErrorAction SilentlyContinue) {
    foreach ($server in @("vercel", "webflow")) {
        $result = agent mcp disable $server 2>&1
        if ($LASTEXITCODE -eq 0) {
            LogOk "$server disabled in Cursor"
        } else {
            LogError "Failed to disable $server in Cursor: $result"
        }
    }
} else {
    Log "Cursor CLI (agent) not found - disable vercel/webflow manually:"
    Log "  Cursor Settings > Features > MCP > toggle off vercel and webflow"
    Log "  Or install Cursor CLI: aitools install"
}

Write-Summary "ACTION" "" "Restart Cursor IDE to apply MCP changes"

# --- Exit ---
if ($errors -gt 0) {
    Log "FAILED with $errors error(s). See log: $logFile"
    exit 1
} else {
    Log "COMPLETED successfully"
    exit 0
}
